import{_ as a,o as i,c as n,aj as t}from"./chunks/framework.BdtAaXf2.js";const e="/assets/image-20250105085559069.Ct9fhS8p.png",l="/assets/image-20250105085914214.BW5d1Ybs.png",p="/assets/image-20250105090015220.D3RNCrNf.png",h="/assets/image-20250105090145764.kzveL9Be.png",r="/assets/image-20250105090203370.UqDWS0E1.png",k="/assets/image-20250105091240519.CUnjzAJH.png",E="/assets/v2-c804989b7362556b57257f80d61f28bf_b.CJD3BydH.webp",g="/assets/image-20250105091007706.BlJOVv4n.png",d="/assets/image-20250105091324817.AmmuJbwV.png",c="/assets/v2-03d033438586009d74ef41c46abbbf9b_b.QejTR8zk.webp",o="/assets/image-20250105091128806.BhrE4GKl.png",m="/assets/image-20250105092307492.CH9Qr1Ye.png",y="/assets/image-20250105092847039.DRJeQod8.png",D=JSON.parse('{"title":"鸿蒙元服务实战-笑笑五子棋（3）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（3）/鸿蒙元服务实战-笑笑五子棋（3）.md","filePath":"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（3）/鸿蒙元服务实战-笑笑五子棋（3）.md","lastUpdated":1736065935000,"__rawMarkdown":"# 鸿蒙元服务实战-笑笑五子棋（3）\\n\\n接上篇。上一篇主要讲解了元服务的创建和 canvas 的一些基本使用，直线、矩形、弧形、文本、图像等。canvas 本身还有很多其他\\n\\n的功能。这里继续围绕 canvas 进行讲解。\\n\\n## createPattern\\n\\n> createPattern(image: ImageBitmap, repetition: string | null): CanvasPattern | null\\n\\n通过指定图像和重复方式创建图片填充的模板。\\n\\n| 参数名     | 类型                                                                                                                    | 必填 | 说明                                                                                                                                                                                                                                                         |\\n| :--------- | :---------------------------------------------------------------------------------------------------------------------- | :--- | :----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| image      | [ImageBitmap](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/ts-components-canvas-imagebitmap-V5) | 是   | 图源对象，具体参考 ImageBitmap 对象。                                                                                                                                                                                                                        |\\n| repetition | string \\\\| null                                                                                                          | 是   | 设置图像重复的方式：\'repeat\'：沿 x 轴和 y 轴重复绘制图像；\'repeat-x\'：沿 x 轴重复绘制图像；\'repeat-y\'：沿 y 轴重复绘制图像；\'no-repeat\'：不重复绘制图像；\'clamp\'：在原始边界外绘制时，超出部分使用边缘的颜色绘制；\'mirror\'：沿 x 轴和 y 轴重复翻转绘制图像。 |\\n\\n提前准备好图片\\n\\n![image-20250105085559069](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/image-20250105085559069.png)\\n\\n### 基本使用\\n\\n1. 基于图片创建填充模版\\n2. 设置到 canvas 的 fillStyle 中\\n3. 进行描绘\\n\\n```jsx\\n@Entry\\n@Component\\nstruct Index {\\n  private settings: RenderingContextSettings = new RenderingContextSettings(true)\\n  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)\\n  private img: ImageBitmap = new ImageBitmap(\\"/images/2.png\\")\\n\\n  build() {\\n    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {\\n      Canvas(this.context)\\n        .width(\'100%\')\\n        .height(\'100%\')\\n        .backgroundColor(\'#ffff00\')\\n        .onReady(() => {\\n          // 1  基于图片创建填充模版\\n2.\\n          let pattern = this.context.createPattern(this.img, \'no-repeat\') // 不平铺\\n          if (pattern) {\\n            // 2 设置到canvas的fillStyle中\\n            this.context.fillStyle = pattern\\n          }\\n          // 3 进行描绘\\n          this.context.fillRect(0, 0, 400, 400)\\n        })\\n    }\\n    .width(\'100%\')\\n    .height(\'100%\')\\n  }\\n}\\n```\\n\\n**效果**：\\n\\n![image-20250105085914214](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/image-20250105085914214.png)\\n\\n### repetition：repeat\\n\\n设置平铺\\n\\n```jsx\\nlet pattern = this.context.createPattern(this.img, \\"repeat\\");\\n```\\n\\n**效果**\\n\\n![image-20250105090015220](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/image-20250105090015220.png)\\n\\n### clamp\\n\\n> 在原始边界外绘制时，超出部分使用边缘的颜色绘制；\\n\\n```jsx\\nlet pattern = this.context.createPattern(this.img, \\"clamp\\");\\n```\\n\\n![image-20250105090145764](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/image-20250105090145764.png)\\n\\n### mirror\\n\\n> 沿 x 轴和 y 轴重复翻转绘制图像。\\n\\n```jsx\\nlet pattern = this.context.createPattern(this.img, \\"mirror\\");\\n```\\n\\n![image-20250105090203370](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/image-20250105090203370.png)\\n\\n## quadraticCurveTo\\n\\n> quadraticCurveTo(cpx: number, cpy: number, x: number, y: number): void\\n\\n创建二次贝赛尔曲线的路径。\\n\\n| 参数名 | 类型   | 必填 | 说明                                  |\\n| :----- | :----- | :--- | :------------------------------------ |\\n| cpx    | number | 是   | 贝塞尔参数的 x 坐标值。默认单位：vp。 |\\n| cpy    | number | 是   | 贝塞尔参数的 y 坐标值。默认单位：vp。 |\\n| x      | number | 是   | 路径结束时的 x 坐标值。默认单位：vp。 |\\n| y      | number | 是   | 路径结束时的 y 坐标值。默认单位：vp。 |\\n\\n**示例代码**\\n\\n```jsx\\nthis.context.beginPath();\\nthis.context.moveTo(20, 20);\\nthis.context.quadraticCurveTo(100, 100, 200, 20);\\nthis.context.stroke();\\n```\\n\\n**效果**\\n\\n![image-20250105091240519](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/image-20250105091240519.png)\\n\\n**辅助理解**\\n\\n![img](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/v2-c804989b7362556b57257f80d61f28bf_b.webp)\\n\\n---\\n\\n![image-20250105091007706](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/image-20250105091007706.png)\\n\\n## bezierCurveTo\\n\\n> bezierCurveTo(cp1x: number, cp1y: number, cp2x: number, cp2y: number, x: number, y: number): void\\n\\n创建三次贝赛尔曲线的路径。\\n\\n| 参数名 | 类型   | 必填 | 说明                                        |\\n| :----- | :----- | :--- | :------------------------------------------ |\\n| cp1x   | number | 是   | 第一个贝塞尔参数的 x 坐标值。默认单位：vp。 |\\n| cp1y   | number | 是   | 第一个贝塞尔参数的 y 坐标值。默认单位：vp。 |\\n| cp2x   | number | 是   | 第二个贝塞尔参数的 x 坐标值。默认单位：vp。 |\\n| cp2y   | number | 是   | 第二个贝塞尔参数的 y 坐标值。默认单位：vp。 |\\n| x      | number | 是   | 路径结束时的 x 坐标值。默认单位：vp。       |\\n| y      | number | 是   | 路径结束时的 y 坐标值。默认单位：vp。       |\\n\\n**示例代码**\\n\\n```\\n  this.context.beginPath()\\n  this.context.moveTo(10, 10)\\n  this.context.bezierCurveTo(20, 100, 200, 100, 200, 20)\\n  this.context.stroke()\\n```\\n\\n**效果**\\n\\n![image-20250105091324817](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/image-20250105091324817.png)\\n\\n**辅助理解**\\n\\n![img](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/v2-03d033438586009d74ef41c46abbbf9b_b.webp)\\n\\n![image-20250105091128806](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/image-20250105091128806.png)\\n\\n## ImageData\\n\\n[ImageData](https://developer.mozilla.org/zh-CN/docs/Web/API/ImageData)对象可以存储 canvas 渲染的像素数据。也就是说 ImageData 可以让我们使用 canvas 对画布中的每一个像素进行操作。提\\n\\n供了强大的控制能力。\\n\\n### [实例属性](https://developer.mozilla.org/zh-CN/docs/Web/API/ImageData#属性)\\n\\n- [`ImageData.data`](https://developer.mozilla.org/zh-CN/docs/Web/API/ImageData/data) 只读\\n\\n  [`Uint8ClampedArray`](https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Uint8ClampedArray) 描述了一个一维数组，包含以 RGBA 顺序的数据，数据使用 `0` 至 `255`（包含）的整数表示。\\n\\n- [`ImageData.height`](https://developer.mozilla.org/zh-CN/docs/Web/API/ImageData/height) 只读\\n\\n  无符号长整型（`unsigned long`），使用像素描述 **ImageData** 的实际高度。\\n\\n- [`ImageData.width`](https://developer.mozilla.org/zh-CN/docs/Web/API/ImageData/width) 只读\\n\\n  无符号长整型（`unsigned long`），使用像素描述 **ImageData** 的实际宽度。\\n\\n这里通过 canvas 的[getImageData](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V13/ts-offscreencanvasrenderingcontext2d-V13#getimagedata)方法快速获取 ImageData 数据。然后通过[putImageData](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V13/ts-offscreencanvasrenderingcontext2d-V13#putimagedata)把处理好的内容重新描绘到画图上。\\n\\n```jsx\\n@Entry\\n@Component\\nstruct Index {\\n  private settings: RenderingContextSettings = new RenderingContextSettings(true)\\n  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)\\n  private img: ImageBitmap = new ImageBitmap(\\"/images/2.png\\")\\n\\n  build() {\\n    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {\\n      Canvas(this.context)\\n        .width(\'100%\')\\n        .height(\'100%\')\\n        .backgroundColor(\'#ffff00\')\\n        .onReady(() => {\\n          this.context.drawImage(this.img, 0, 0, 130, 130)\\n          // 获取了 ImageData 示例\\n          let imagedata = this.context.getImageData(50, 50, 130, 130)\\n          // 又重新描绘到canvas上\\n          this.context.putImageData(imagedata, 150, 150)\\n        })\\n    }\\n    .width(\'100%\')\\n    .height(\'100%\')\\n  }\\n}\\n```\\n\\n**效果**\\n\\n![image-20250105092307492](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/image-20250105092307492.png)\\n\\n## ImageData 反色\\n\\n```jsx\\nthis.context.drawImage(this.img, 0, 0, 130, 130);\\n// 获取了 ImageData 示例\\nlet imagedata = this.context.getImageData(50, 50, 130, 130);\\n// console.log(\\"xxx,\\", JSON.stringify(imagedata.data))\\nObject.keys(imagedata.data).forEach((k) => {\\n  // 反色\\n  imagedata.data[k] = 255 - imagedata.data[k];\\n});\\n// 又重新描绘到canvas上\\nthis.context.putImageData(imagedata, 150, 150);\\n```\\n\\n![image-20250105092847039](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%883%EF%BC%89.assets/image-20250105092847039.png)\\n\\n## ImageData 其他效果\\n\\n反转效果：\\n\\n- 原理：通过将每个像素的 RGB 值取反来实现反转效果。\\n- 实现方式：使用`getImageData`获取图像数据，然后遍历每个像素，将每个像素的 RGB 值取反，再使用`putImageData`将修改后的数据绘制回 Canvas。\\n\\n黑白效果：\\n\\n- 原理：将每个像素的 RGB 值转换为灰度值，使图像变为黑白。\\n- 实现方式：使用`getImageData`获取图像数据，然后遍历每个像素，将每个像素的 RGB 值转换为灰度值（R、G、B 三个分量取平均值），再使用`putImageData`将修改后的数据绘制回 Canvas。\\n\\n亮度效果：\\n\\n- 原理：调整每个像素的亮度值，使图像变亮或变暗。\\n- 实现方式：使用`getImageData`获取图像数据，然后遍历每个像素，调整每个像素的亮度值，再使用`putImageData`将修改后的数据绘制回 Canvas。\\n\\n复古效果：\\n\\n- 原理：通过调整每个像素的色调、饱和度和亮度，使图像呈现复古效果。\\n- 实现方式：使用`getImageData`获取图像数据，然后遍历每个像素，调整每个像素的色调、饱和度和亮度，再使用`putImageData`将修改后的数据绘制回 Canvas。\\n\\n红色、绿色、蓝色效果：\\n\\n- 原理：增加或减少每个像素的红色、绿色、蓝色分量的值，使图像呈现相应颜色的效果。\\n- 实现方式：使用`getImageData`获取图像数据，然后遍历每个像素，增加或减少每个像素的红色、绿色、蓝色分量的值，再使用`putImageData`将修改后的数据绘制回 Canvas。\\n\\n透明效果：\\n\\n- 原理：调整每个像素的透明度值，使图像呈现透明效果。\\n- 实现方式：使用`getImageData`获取图像数据，然后遍历每个像素，调整每个像素的透明度值，再使用`putImageData`将修改后的数据绘制回 Canvas。\\n\\n马赛克效果：\\n\\n- 原理：将图像分割为小块，每个小块的像素值设置为该小块内像素的平均值，从而实现马赛克效果。\\n- 实现方式：使用`getImageData`获取图像数据，然后将图像分割为小块，计算每个小块内像素的平均值，再将该小块内所有像素的值设置为该平均值，最后使用`putImageData`将修改后的数据绘制回 Canvas。\\n\\n马赛克效果\\n\\n- 由于实际操作过程中，上述马赛克效果处理性能比较底下，这里用来一个取巧的效果来实现。就是先用 canvas 将画面画小，然后再将画面缩放来实现一个模糊效果，间接实现马赛克效果\\n\\n渐变滤镜效果：\\n\\n- 原理：通过在图像上应用渐变效果，使图像呈现渐变色的效果。\\n- 实现方式：使用`createLinearGradient`或`createRadialGradient`创建渐变对象，然后使用渐变对象作为填充样式，绘制图像到 Canvas 上。\\n\\n## 参考链接\\n\\n1. [数学曲线之一：贝塞尔曲线](https://zhuanlan.zhihu.com/p/711975272)\\n2. [神奇 canvas 带你实现魔法摄像头](https://juejin.cn/post/7264125562393788473#heading-8)\\n3. [ImageData](https://developer.mozilla.org/zh-CN/docs/Web/API/ImageData)\\n"}'),b={name:"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（3）/鸿蒙元服务实战-笑笑五子棋（3）.md"};function C(u,s,F,x,B,v){return i(),n("div",null,[...s[0]||(s[0]=[t("",83)])])}const f=a(b,[["render",C]]);export{D as __pageData,f as default};
